sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.script:
(function() {
	var language = gs.getSession().getLanguage();//gs.getMessage($sp.getParameter("language"));
	var caseNumber = gs.getMessage($sp.getParameter("requestNumber"));
	//x_hccc_hoc_ohs_vaccination_appointment.do?sys_id=487fc8f01beb0a109fde86acdd4bcb65
	var apptSysId = new GlideRecordSecure('x_hccc_hoc_ohs_vaccination_appointment');
	apptSysId.get('number', caseNumber);
	var message = "";
	if (language == "en"){

		message+= 'The appointment has been created. The appointment number is <a target="_blank" href="/x_hccc_hoc_ohs_vaccination_appointment?sys_id='+ apptSysId.sys_id + '">' + caseNumber + '</a><br><br>';

	}
	if (language == "fq"){

			message+= "<br>Bonne journée,<br><br> Votre demande a été soumise avec succès. Le numéro de dossier est {caseNumber}. <br><br>";

	}


	data.message = message;

})();
